// Pelne kolo z wycieta ikona: przez wyciecie przeswituje szklo
const cutoutSvg = (
    icon: string
) => `<svg xmlns="http://www.w3.org/2000/svg" width="400" height="400" viewBox="0 0 400 400">
  <defs><mask id="cut">
    <rect width="400" height="400" fill="#fff"/>
    <g transform="translate(97 97) scale(8.6)" fill="none" stroke="#000" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round">${ICONS[icon] ?? ICONS.mail}</g>
  </mask></defs>
  <circle cx="200" cy="200" r="190" fill="#000" mask="url(#cut)"/></svg>`

// Wlasna ikona (SVG/PNG z przezroczystoscia): wycinamy jej ksztalt z kola na canvasie
async function cutoutUrl(icon: string, customSrc?: string): Promise<string> {
    if (icon === "custom" && customSrc) {
        const img = new Image()
        img.crossOrigin = "anonymous"
        img.src = customSrc
        await img.decode()
        const c = document.createElement("canvas")
        c.width = c.height = 400
        const ctx = c.getContext("2d")!
        ctx.beginPath()
        ctx.arc(200, 200, 190, 0, Math.PI * 2)
        ctx.fill()
        ctx.globalCompositeOperation = "destination-out"
        const box = 206
        const iw = img.naturalWidth || box,
            ih = img.naturalHeight || box
        const k = Math.min(box / iw, box / ih)
        ctx.drawImage(
            img,
            200 - (iw * k) / 2,
            200 - (ih * k) / 2,
            iw * k,
            ih * k
        )
        const blob = await new Promise<Blob | null>((r) =>
            c.toBlob(r, "image/png")
        )
        if (!blob) throw new Error("cutout")
        return URL.createObjectURL(blob)
    }
    return URL.createObjectURL(
        new Blob([cutoutSvg(icon)], { type: "image/svg+xml" })
    )
}

// Statyczna kulka: gotowe klatki tego samego metalu; wlasna ikone wycinamy maska
function staticOrb(icon: string, customSrc?: string): React.CSSProperties {
    if (icon === "custom" && customSrc) {
        const v = `url("${customSrc}") center / 52% 52% no-repeat, linear-gradient(#000, #000)`
        return {
            backgroundImage: `url(${STATIC_ORBS.blank})`,
            WebkitMask: v,
            mask: v,
            WebkitMaskComposite: "xor",
            maskComposite: "exclude",
        } as React.CSSProperties
    }
    return { backgroundImage: `url(${STATIC_ORBS[icon] ?? STATIC_ORBS.mail})` }
}

